package com.ecole.gestion_scolaire.hr.service; import com.ecole.gestion_scolaire.hr.dto.*; import com.ecole.gestion_scolaire.hr.entity.*; import com.ecole.gestion_scolaire.hr.repository.*; import com.ecole.gestion_scolaire.common.exception.*; import com.ecole.gestion_scolaire.identity.repository.UserAccountRepository; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; @Service @Transactional public class EmployeeProfileService { private final EmployeeRepository employees; private final EmployeeQualificationRepository qualifications; private final EmploymentHistoryRepository histories; private final EmploymentContractRepository contracts; private final EmployeeEmergencyContactRepository contacts; private final EmployeeAdminDocumentRepository documents; private final StaffNoteRepository notes; private final UserAccountRepository users; public EmployeeProfileService(EmployeeRepository e,EmployeeQualificationRepository q,EmploymentHistoryRepository h,EmploymentContractRepository c,EmployeeEmergencyContactRepository x,EmployeeAdminDocumentRepository d,StaffNoteRepository n,UserAccountRepository u){employees=e;qualifications=q;histories=h;contracts=c;contacts=x;documents=d;notes=n;users=u;} private Employee emp(Long id){return employees.findById(id).orElseThrow(()->new ResourceNotFoundException("Employé introuvable"));} public EmployeeQualification addQualification(Long id,QualificationRequest q){var x=new EmployeeQualification();x.setEmployee(emp(id));x.setQualificationType(q.qualificationType());x.setTitle(q.title());x.setInstitution(q.institution());x.setSpecialty(q.specialty());x.setObtainedDate(q.obtainedDate());x.setDescription(q.description());return qualifications.save(x);} public EmploymentHistory addHistory(Long id,HistoryRequest q){var x=new EmploymentHistory();x.setEmployee(emp(id));x.setInstitutionName(q.institutionName());x.setPositionTitle(q.positionTitle());x.setStartDate(q.startDate());x.setEndDate(q.endDate());x.setDescription(q.description());return histories.save(x);} public EmploymentContract addContract(Long id,ContractRequest q){var x=new EmploymentContract();x.setEmployee(emp(id));x.setContractNumber(q.contractNumber());x.setContractType(q.contractType());x.setStartDate(q.startDate());x.setEndDate(q.endDate());x.setPositionTitle(q.positionTitle());x.setWorkloadType(q.workloadType());x.setWeeklyHours(q.weeklyHours());x.setStatus(q.status()==null?"ACTIVE":q.status());x.setNotes(q.notes());return contracts.save(x);} public EmployeeEmergencyContact addContact(Long id,EmergencyContactRequest q){var x=new EmployeeEmergencyContact();x.setEmployee(emp(id));x.setName(q.name());x.setRelationship(q.relationship());x.setPhone(q.phone());x.setSecondaryPhone(q.secondaryPhone());x.setPrimaryContact(q.primaryContact());return contacts.save(x);} public EmployeeAdminDocument addDocument(Long id,AdminDocumentRequest q){var x=new EmployeeAdminDocument();x.setEmployee(emp(id));x.setDocumentType(q.documentType());x.setDocumentNumber(q.documentNumber());x.setIssuedOn(q.issuedOn());x.setExpiresOn(q.expiresOn());x.setFileReference(q.fileReference());x.setStatus(q.status()==null?com.ecole.gestion_scolaire.hr.enums.DocumentStatus.VALID:q.status());x.setNotes(q.notes());return documents.save(x);} public StaffNote addNote(Long id,StaffNoteRequest q){var x=new StaffNote();x.setEmployee(emp(id));x.setCategory(q.category());x.setContent(q.content());x.setCreatedBy(users.findByUsername(SecurityContextHolder.getContext().getAuthentication().getName()).orElse(null));return notes.save(x);} @Transactional(readOnly=true) public Map<String,Object> profile(Long id){emp(id);var m=new LinkedHashMap<String,Object>();m.put("qualifications",qualifications.findByEmployeeIdOrderByObtainedDateDesc(id));m.put("employmentHistory",histories.findByEmployeeIdOrderByStartDateDesc(id));m.put("contracts",contracts.findByEmployeeIdOrderByStartDateDesc(id));m.put("emergencyContacts",contacts.findByEmployeeIdOrderByPrimaryContactDescNameAsc(id));m.put("documents",documents.findByEmployeeId(id));m.put("notes",notes.findByEmployeeIdOrderByCreatedAtDesc(id));return m;} }